package com.andye.warmod.warhead.network;import com.andye.warmod.WarMod;import com.andye.warmod.warhead.*;import java.util.UUID;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;public record ClientboundWarheadImpactPayload(UUID warheadId,double impactX,double impactY,double impactZ,long impactGameTime,long visualSeed,WarheadPayloadType payloadType,float impactVisualScale,WarheadEffectProfile effectProfile)implements CustomPacketPayload{public static final Type<ClientboundWarheadImpactPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"warhead_impact"));public static final StreamCodec<RegistryFriendlyByteBuf,ClientboundWarheadImpactPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeUUID(p.warheadId);b.writeDouble(p.impactX);b.writeDouble(p.impactY);b.writeDouble(p.impactZ);b.writeLong(p.impactGameTime);b.writeLong(p.visualSeed);b.writeVarInt(p.payloadType.ordinal());b.writeFloat(p.impactVisualScale);b.writeVarInt(p.effectProfile.ordinal());},b->new ClientboundWarheadImpactPayload(b.readUUID(),b.readDouble(),b.readDouble(),b.readDouble(),b.readLong(),b.readLong(),WarheadPayloadType.values()[b.readVarInt()],b.readFloat(),WarheadEffectProfile.values()[b.readVarInt()]));public boolean isWellFormed(){return warheadId!=null&&payloadType!=null&&effectProfile!=null&&Double.isFinite(impactX)&&Double.isFinite(impactY)&&Double.isFinite(impactZ)&&Float.isFinite(impactVisualScale)&&impactVisualScale>=.05F&&impactVisualScale<=8;}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}